import{_ as a,H as n,f as t,i as s}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"08｜俯视项目全景：用提示词画出架构图、模块图、依赖图","description":"","frontmatter":{},"headers":[{"level":2,"title":"先把项目 clone 下来","slug":"先把项目-clone-下来","link":"#先把项目-clone-下来","children":[]},{"level":2,"title":"为什么先画三张图","slug":"为什么先画三张图","link":"#为什么先画三张图","children":[]},{"level":2,"title":"开始画图","slug":"开始画图","link":"#开始画图","children":[{"level":3,"title":"第一张：架构图","slug":"第一张-架构图","link":"#第一张-架构图","children":[]},{"level":3,"title":"第二张：模块图","slug":"第二张-模块图","link":"#第二张-模块图","children":[]},{"level":3,"title":"第三张：依赖图","slug":"第三张-依赖图","link":"#第三张-依赖图","children":[]}]},{"level":2,"title":"画完不是终点，review 和存档才是","slug":"画完不是终点-review-和存档才是","link":"#画完不是终点-review-和存档才是","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ClaudeCode企业级老项目改造实战/08｜俯视项目全景：用提示词画出架构图、模块图、依赖图.md","filePath":"ClaudeCode企业级老项目改造实战/08｜俯视项目全景：用提示词画出架构图、模块图、依赖图.md","lastUpdated":1779815445000}'),i={name:"ClaudeCode企业级老项目改造实战/08｜俯视项目全景：用提示词画出架构图、模块图、依赖图.md"};function p(o,e,r,l,c,d){return n(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="_08-俯视项目全景-用提示词画出架构图、模块图、依赖图" tabindex="-1">08｜俯视项目全景：用提示词画出架构图、模块图、依赖图 <a class="header-anchor" href="#_08-俯视项目全景-用提示词画出架构图、模块图、依赖图" aria-label="Permalink to &quot;08｜俯视项目全景：用提示词画出架构图、模块图、依赖图&quot;">​</a></h1><p>你好，我是 Robert。</p><p>上一讲装好了画图能力，这一讲我们正式拿 Spring AI Alibaba Admin 开刀，开始干活了。</p><p>从这一讲开始，第二部分剩下的五讲（08 到 12），每一讲都在这个项目上做事。 <strong>所有出现的提示词、产出的图、沉淀的文档，都围绕它展开。你跟着一起操作会收获最大</strong>。</p><h2 id="先把项目-clone-下来" tabindex="-1">先把项目 clone 下来 <a class="header-anchor" href="#先把项目-clone-下来" aria-label="Permalink to &quot;先把项目 clone 下来&quot;">​</a></h2><p>花两分钟准备一下：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/alibaba/spring-ai-alibaba.git</span></span>
<span class="line"><span>cd spring-ai-alibaba/spring-ai-alibaba-admin</span></span></code></pre></div><p><strong>这一讲只看代码、不跑项目</strong>。你可能手痒想 <code>mvn spring-boot:run</code> 跑起来看看，先按住这个冲动。13 讲专门讲怎么让 AI 帮你把编译运行搞定，那时候一次性讲透。这一讲我们只让 AI 读代码、画图。</p><p><strong>一个约定</strong>：后面我们课程里所有产出的图、文档、学习笔记，都统一放在 <code>docs/</code> 目录下。这是一个固定的规范，不会变。我们今天画的三张图就是第一批住进 <code>docs/</code> 的资产。准备好了就开始。</p><h2 id="为什么先画三张图" tabindex="-1">为什么先画三张图 <a class="header-anchor" href="#为什么先画三张图" aria-label="Permalink to &quot;为什么先画三张图&quot;">​</a></h2><p>老项目改造八步心法的第 4 步是“画项目全景”。全景不是一张图，是三张。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/975832/b95b8b1495bd28f4d1f7c465349a1d70.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/975832/b95b8b1495bd28f4d1f7c465349a1d70.png" alt=""></a></p><p><strong>架构图回答“这个项目长什么样”</strong>。前端、后端、数据库、中间件的系统边界和调用关系。一张图告诉你，这是个什么样的系统、跑起来的时候各部分怎么协作。是 <strong>系统级</strong> 的俯视。</p><p><strong>模块图回答“项目内部怎么组织”</strong>。具体到代码仓库里的模块划分和模块之间的依赖关系。一张图告诉你，这个仓库里有几个模块、谁依赖谁、改一个会拖动谁。是 <strong>代码级</strong> 的俯视。</p><p><strong>依赖图回答“项目靠什么外部能力活着”</strong>。这个项目用了哪些第三方库、连了哪些中间件、对接了哪些外部 API。一张图告诉你，这个系统的生存环境长什么样、哪些外部依赖不能丢。是 <strong>生态级</strong> 的俯视。</p><p>三张图不重复，它们从三个不同的高度俯视同一个项目。</p><h2 id="开始画图" tabindex="-1">开始画图 <a class="header-anchor" href="#开始画图" aria-label="Permalink to &quot;开始画图&quot;">​</a></h2><p>你可能觉得，画一张架构图也就罢了，另外两张真有必要吗？真有必要。每一张图解决一个你迟早会遇到的具体问题。</p><p><strong>没有架构图</strong>，你和 AI 对这个项目的基线认知不同步。后面每次让 AI 改造，它都要重新猜一次项目长什么样。你猜一个版本，AI 猜另一个版本，改着改着就跑偏了。架构图的作用是锚定共同认知，改造之前先对表。</p><p><strong>没有模块图</strong>，你不知道一个改动的辐射范围。改 server-core 会不会波及 server-runtime？改 server-openapi 会不会动到 server-start？这些问题，没有模块图你只能看 pom.xml 一行一行翻。有了图，影响范围一眼就看清。</p><p><strong>没有依赖图</strong>，你不知道项目的命门在哪。升级 Spring AI 的版本会不会炸？Nacos 连不上整个应用还能不能启动？MySQL 换成 PostgreSQL 要改几处？这些都是依赖图一眼看得到的事情。</p><p>还有一个更关键的理由： <strong>这三张图是 10 讲 CLAUDE.md 的前置资产</strong>。写 CLAUDE.md 时你需要给 AI 一份项目概貌，三张图就是概貌的骨架。今天画好，明天就能用上。理论讲完，开始画。</p><p>你可以直接复制下面的提示词到你自己的项目运行，生成自己的架构图、模块图、依赖图。</p><p>提示：这些图在上一节课已经出现过，但是上一讲是演示画图效果，本节课才是真正的开始了解项目。</p><h3 id="第一张-架构图" tabindex="-1">第一张：架构图 <a class="header-anchor" href="#第一张-架构图" aria-label="Permalink to &quot;第一张：架构图&quot;">​</a></h3><p><strong>提示词</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读一下这个项目的 README 和顶层目录，给我画一张架构图。</span></span>
<span class="line"><span>前端、后端、数据库、中间件分层画，核心模块写一句话职责。</span></span>
<span class="line"><span>周边基础设施（日志、监控、配置）用一个方框概括就行，</span></span>
<span class="line"><span>不用展开。保存到 docs/architecture.svg。</span></span></code></pre></div><p><strong>关键点</strong>：</p><p>分层说清楚。Spring AI Alibaba Admin 是前后端分离的项目，前端 React 一层、后端 Java 一层、下面挂 MySQL 和 Nacos、在下面对接外部模型 API。没有分层的提示，AI 会把所有东西堆到一起。</p><p>“核心模块写一句话职责”，这一条很关键。AI 默认只写模块名，画出来的图每个方框里只有一个词，别人看了还是不知道 server-core 到底是干嘛的。加一句职责，图的信息密度立刻上来。</p><p>画出来的效果如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/975832/cc4e5c990c7c820583138cd1b35805cf.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/975832/cc4e5c990c7c820583138cd1b35805cf.png" alt=""></a></p><p><strong>常见坑</strong>：</p><p>第一个坑，AI 容易把 frontend 画成一个跟后端并列的小方框，实际上 frontend 是一整个独立的前端工程。review 的时候看一下，前端是不是被合理展开、UI 路由和后端 API 的调用关系是不是画出来了。</p><p>第二个坑，AI 容易漏掉 OpenTelemetry。Spring AI Alibaba Admin 的 observability 能力是通过 OTel 集成实现的，架构图里应该体现“服务发出 trace → OTel Collector → 存储”这条链路。第一张出来如果没画，你直接说“把 OpenTelemetry trace 链路补上”，AI 会基于上下文迭代一版。</p><p>第三个坑，一次画不完美是常态。画完说“放大 Server 层，把四个子模块之间的调用关系画细一点”，“数据库层加上表名”。迭代三五轮才能拿到一张真正能用的架构图。</p><h3 id="第二张-模块图" tabindex="-1">第二张：模块图 <a class="header-anchor" href="#第二张-模块图" aria-label="Permalink to &quot;第二张：模块图&quot;">​</a></h3><p><strong>提示词</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>看一下项目的 pom.xml，画一张内部模块依赖图。</span></span>
<span class="line"><span>只画项目自己的模块，外部库不画。有循环依赖用红色标出来。</span></span>
<span class="line"><span>保存到 docs/module-deps.svg。</span></span></code></pre></div><p><strong>关键点</strong>：</p><p>强调“看 pom.xml”。Spring AI Alibaba Admin 下面有四个 server 子模块加一个 frontend，AI 只要读 parent pom 和各子模块的 pom，关系就清楚了。不让它读，它可能根据模块名瞎猜依赖方向。</p><p>“外部库不画”也是必须的。Spring Boot 一个项目 transitive 依赖能到几百个，全画进来图就废了。</p><p>画出来的效果如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/975832/110ef8283461288aff685c311b0ceac8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/975832/110ef8283461288aff685c311b0ceac8.png" alt=""></a></p><p><strong>常见坑</strong>：</p><p>第一个坑，AI 可能把 server-start 模块漏掉。start 模块通常是 entry point（main 方法在里面），AI 容易认为它是“运行时入口”而不是“代码模块”。review 的时候看 start 模块有没有在图里，以及它有没有正确地依赖其他三个 server 模块。</p><p>第二个坑，依赖方向可能画反。正确的方向是 start 依赖 runtime 和 openapi，openapi 和 runtime 都依赖 core。如果图里出现 core 反过来依赖 runtime 这种，就是错的，要让 AI 重画。</p><p>第三个坑，frontend 不应该出现在这张图里。模块图只画 Java 模块之间的依赖关系，frontend 是独立的 React 工程，通过 HTTP 调用后端，不通过 Maven 依赖。AI 有时候会把 frontend 也塞进去，要让它去掉。</p><h3 id="第三张-依赖图" tabindex="-1">第三张：依赖图 <a class="header-anchor" href="#第三张-依赖图" aria-label="Permalink to &quot;第三张：依赖图&quot;">​</a></h3><p><strong>提示词</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>综合看 pom.xml、application.yml 和 README，帮我梳理这个项目。</span></span>
<span class="line"><span>对外依赖了什么，分成三类：关键 Java 依赖、中间件、外部 API。</span></span>
<span class="line"><span>画出来，每类用不同颜色。保存到 docs/external-deps.svg。</span></span></code></pre></div><p><strong>关键点</strong>：</p><p>分三类是这张图的灵魂。Java 依赖看 pom（Spring AI、Spring Boot Actuator、Micrometer 等），中间件看 application.yml 和 docker-compose（MySQL、Nacos、OTel Collector），外部 API 看 README 和配置样例（DashScope、OpenAI、DeepSeek 等模型提供商）。</p><p>三类分开画，你才能一眼分辨，哪些是代码层面的依赖、哪些是运行时要连的中间件、哪些是外部第三方服务。</p><p>画出来的效果如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/975832/5f49a9a61e6d7ebab7288029779e6e1f.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/975832/5f49a9a61e6d7ebab7288029779e6e1f.png" alt=""></a></p><p><strong>常见坑</strong>：</p><p>第一个坑，AI 容易把 transitive dependency 全列出来。Spring Boot 一个 starter 就能拉几十个间接依赖，全画进来就没法看了。提示词里强调“关键”，review 的时候挑出真正的项目主干依赖，砍掉无关的。</p><p>第二个坑，AI 可能不知道“应该看 application.yml 才知道中间件”。如果第一版画出来只有 Java 依赖没有中间件，直接告诉它“去读 application.yml 和 application-*.yml，看项目连了什么中间件”。</p><p>第三个坑，外部模型 API 这一类容易漏。因为它们在代码里是通过配置注入的，不在 pom.xml 里。README 的 Configure Your API Keys 一节会说清楚项目支持哪些 API。让 AI 读 README 的这一节。</p><h2 id="画完不是终点-review-和存档才是" tabindex="-1">画完不是终点，review 和存档才是 <a class="header-anchor" href="#画完不是终点-review-和存档才是" aria-label="Permalink to &quot;画完不是终点，review 和存档才是&quot;">​</a></h2><p>07 讲留了一条硬线： <strong>AI 画的图一定有错</strong>。这一讲把这条线具体化。</p><p>架构图画完先问自己几个问题。 <strong>核心模块是不是都在？前端后端的边界是不是画对了？数据流向是不是真实？有没有把 observability 漏掉？有没有把已经废弃的东西画成核心？</strong> 问到哪一条不对，就让 AI 调到对为止。</p><p>这一步是需要停下来的，因为 AI 完成了主要工作，需要我们自己来做校对。但是不一定全对，只要大致对即可。</p><p>模块图 review 的重点是依赖方向。start 依赖 runtime 和 openapi，runtime 和 openapi 依赖 core。这个方向一定要对。循环依赖出现了不要忽略，这是真实存在的架构问题。</p><p>依赖图 review 的重点是三类是不是齐全，Java 依赖有没有列主干？中间件有没有遗漏？外部 API 是不是反映了当前 README 写的那几个模型提供商？</p><p><strong>review 到你满意为止，然后定稿放进 <code>docs/</code></strong>。定稿之后，这三张图就是你和 AI 的共同记忆。10 讲写 CLAUDE.md 会引用它们，后面改造的每一讲都可能翻出来对照。图画得扎实，后面所有课程都轻松。</p><p>如果你画到一半发现某张图特别难画，那通常不是你的问题，是项目本身就有问题。循环依赖是架构问题，模块职责不清也是架构问题，外部依赖一团乱麻更是架构问题。 <strong>画不出整齐的图，说明这个项目本身需要整理</strong>。这本身就是一个信号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一讲做了三件事。</p><ol><li><p>把 Spring AI Alibaba Admin clone 下来，确认从现在开始实操都在这个项目上做，所有产出都放在 <code>docs/</code> 目录下。</p></li><li><p>讲清楚了为什么要画三张图： <strong>架构图锚定系统级共识</strong>、 <strong>模块图暴露代码级依赖</strong>、 <strong>依赖图展示生态级牵挂</strong>。三张图是三种不同粒度的俯视，不重复。</p></li><li><p>给了三套提示词，分别画出这三张图。提示词像人说话的风格，不堆格式化要求，只把关键指令和关键约束说清楚。每一张图都附上常见坑和 review 要点，让你不至于画到一半一头雾水。</p></li></ol><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>你手上正在维护的那个老项目，如果让你画这三张图，哪一张最难画？为什么？是因为项目本身就乱，还是因为你自己没想清楚？</p></li><li><p>架构图、模块图、依赖图这三张图里，团队里哪一张最容易被反复翻出来看？这张图更新频率高不高？如果不高，为什么？是因为项目很稳定，还是因为没人维护？</p></li></ol><p>欢迎在评论区把你的答案写出来。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>`,74)])])}const E=a(i,[["render",p]]);export{h as __pageData,E as default};
